const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
let saved={};try{saved=JSON.parse(localStorage.getItem('aura-prototype-v1')||'{}')}catch{}
const state={theme:saved.theme||'dark',range:'24h',filter:'',provider:'all',status:'all',dataState:'normal',routing:saved.routing||'balanced',fallback:saved.fallback??true,providers:saved.providers||{OpenAI:true,Anthropic:true,Google:true},compression:saved.compression??false,validation:saved.validation??false,model:saved.model||'auto',heroTab:'overview',codeTab:'typescript',inspectorTab:'overview',activeRequest:null,chatStarted:false,messages:[],requests:[],streaming:false,streamTimer:null,sessionName:'Untitled session',savedSession:null};
const persist=()=>{try{localStorage.setItem('aura-prototype-v1',JSON.stringify({theme:state.theme,routing:state.routing,fallback:state.fallback,providers:state.providers,compression:state.compression,validation:state.validation,model:state.model}))}catch{}};
const modelInfo={'gpt-5.4-mini':{provider:'OpenAI',input:1240,output:310,cost:.0032,latency:842},'claude-sonnet-4-5':{provider:'Anthropic',input:1240,output:365,cost:.0092,latency:1206},'gemini-2.5-flash':{provider:'Google',input:1240,output:298,cost:.0017,latency:654}};
const seedRequests=[['req_8f12','OpenAI','gpt-5.4-mini',842,.0032,'Completed','14:32:08'],['req_8f11','Anthropic','claude-sonnet-4-5',1206,.0092,'Completed','14:31:56'],['req_8f10','Google','gemini-2.5-flash',2510,0,'Failed','14:31:42'],['req_8f09','OpenAI','gpt-5.4-mini',726,.0028,'Completed','14:31:30'],['req_8f08','Anthropic','claude-sonnet-4-5',1132,.0086,'Completed','14:30:59'],['req_8f07','Google','gemini-2.5-flash',654,.0017,'Completed','14:30:44'],['req_8f06','OpenAI','gpt-5.4-mini',901,.0036,'Completed','14:30:12'],['req_8f05','OpenAI','gpt-5.4-mini',788,.0031,'Completed','14:29:51']].map(([id,provider,model,latency,cost,status,time])=>({id,provider,model,latency,cost,status,time,input:1240,output:status==='Failed'?0:310,compression:false,routing:'balanced'}));
state.requests=[...seedRequests];
const cost=v=>'$'+v.toFixed(4),duration=v=>v>=1000?(v/1000).toFixed(2)+' s':v+' ms';
const brand=(word=false)=>word?`<img class="wordmark" src="assets/aura-wordmark-${state.theme==='dark'?'dark':'light'}.svg" alt="Aura">`:`<img src="assets/aura-mark-${state.theme==='dark'?'violet':'ink'}.svg" alt=""><span class="brand-word">Aura</span>`;
function applyTheme(){document.documentElement.dataset.theme=state.theme;$('#theme-toggle').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',`Switch to ${state.theme==='dark'?'light':'dark'} theme`)}
$('#theme-toggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';persist();applyTheme();render();};
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function route(){return location.hash.replace(/^#\/?/,'').split('?')[0]||'landing'}
function goto(r){location.hash=r==='landing'?'#/':'#/'+r}
function render(){const r=route();$$('#prototype-bar a').forEach(a=>a.classList.toggle('active',a.dataset.view===(r.startsWith('console')?'console':r==='chat'?'chat':r.startsWith('docs')?'docs':r==='roadmap'?'roadmap':r==='pricing'?'pricing':'landing')));if(r==='pricing')renderPricing();else if(r.startsWith('docs'))renderDocs(r.split('/')[1]||'auto-routing');else if(r==='roadmap')renderRoadmap();else if(r==='chat')renderChat();else if(r.startsWith('console'))renderAdmin(r.split('/')[1]||'overview');else renderLanding();bindCommon();}
window.addEventListener('hashchange',()=>{closeOverlay();render();window.scrollTo(0,0)});
const statusBadge=r=>`<span class="status ${r==='Failed'?'error':r==='Degraded'?'warning':r==='Stopped'?'neutral':''}">${r}</span>`;
function bindCommon(){$('.skip').onclick=e=>{e.preventDefault();const main=$('#main');main.setAttribute('tabindex','-1');main.focus();main.scrollIntoView()};$$('[data-copy]').forEach(b=>b.onclick=()=>copyText(b.dataset.copy));$$('[data-open-request]').forEach(b=>b.onclick=e=>{e.stopPropagation();openRequest(b.dataset.openRequest)});$$('[data-mobile-menu]').forEach(b=>b.onclick=()=>{$('.sidebar').classList.toggle('open');$('.mobile-scrim').classList.toggle('show')});$('.mobile-scrim')?.addEventListener('click',()=>{$('.sidebar').classList.remove('open');$('.mobile-scrim').classList.remove('show')});$$('[data-quickstart]').forEach(b=>b.onclick=openQuickstart);$$('[data-request-settings]').forEach(b=>b.onclick=openChatSettings);$$('[data-reset]').forEach(b=>b.onclick=resetDemo);bindAuto();bindShowcase();}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Copied to clipboard')}catch{toast('Clipboard is unavailable in this browser. Select and copy the text.')}}
function detailOverview(r){return `<div class="request-status">${statusBadge(r.status)}<span class="eyebrow">SAMPLE REQUEST</span></div><dl class="detail-stack"><div><dt>Provider</dt><dd>${esc(r.provider)}</dd></div><div><dt>Model</dt><dd>${esc(r.model)}</dd></div><div><dt>Total duration</dt><dd>${duration(r.latency)}</dd></div><div><dt>Input tokens</dt><dd>${r.input.toLocaleString()}</dd></div><div><dt>Output tokens</dt><dd>${r.output.toLocaleString()}</dd></div><div><dt>Cost</dt><dd>${cost(r.cost)}</dd></div><div><dt>Compression</dt><dd>${r.compression?'Enabled · sample 35%':'Off'}</dd></div></dl><ol class="timeline"><li>Request received<span>0 ms</span></li><li>Provider selected<span>4 ms</span></li><li>${r.status==='Failed'?'Provider unavailable':'First response'}<span>${r.status==='Failed'?'2,500 ms':'186 ms'}</span></li><li>${r.status}<span>${r.latency.toLocaleString()} ms</span></li></ol>`}
function detailRouting(r){if(r.autoDecision)return autoDecisionHTML(r.autoDecision,true);return `<p class="eyebrow">ROUTING DECISION</p><h3 style="font-size:18px;margin:14px 0 9px">${({balanced:'Balanced',cost:'Cost',quality:'Quality',latency:'Lowest latency',manual:'Manual selection'})[r.routing||state.routing]}</h3><p class="muted tiny">Illustrative decision trace. This prototype does not contact a provider.</p><div class="routing-path"><div class="route-step">${icon('shield')}<div>Project policy applied<p>Acme / Production · allowed models</p></div></div><div class="route-step selected">${icon('check')}<div>${esc(r.provider)} selected<p>${esc(r.model)}</p></div></div><div class="route-step">${icon('route')}<div>${state.fallback?'Fallback available':'Fallback disabled'}<p>${state.fallback?'Another enabled provider may be used.':'The selected provider handles the request.'}</p></div></div></div><div class="notice">${icon('alert')}Routing settings here are local demo preferences.</div>`}
function rawRequest(r){return JSON.stringify({id:r.id,object:'response',status:r.status.toLowerCase(),model:r.model,usage:{input_tokens:r.input,output_tokens:r.output,cost_usd:r.cost},metadata:{aura:{provider:r.provider.toLowerCase(),latency_ms:r.latency,...(r.autoDecision?{routing:cleanDecision(r.autoDecision)}:{})}},_prototype:{sample:true,network_request:false}},null,2)}
function detailRaw(r){return `<div class="code-header"><span class="eyebrow">RESPONSE.JSON</span><button class="icon-button" data-copy="${esc(rawRequest(r))}" aria-label="Copy response JSON">${icon('copy')}</button></div><pre class="raw-box">${esc(rawRequest(r))}</pre>`}
function detailContent(r,tab){return tab==='routing'?detailRouting(r):tab==='raw'?detailRaw(r):detailOverview(r)}
function inspectorTabs(active,prefix='detail'){return `<div class="tabs" role="tablist" aria-label="Request details">${['overview','routing','raw'].map(t=>`<button role="tab" aria-selected="${active===t}" class="${active===t?'active':''}" data-${prefix}-tab="${t}">${t==='raw'?'Raw JSON':t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>`}
function renderLanding(){$('#app').innerHTML=`<div class="container"><header class="site-nav"><a class="brand" href="#/" aria-label="Aura home">${brand(true)}</a><nav class="site-links" aria-label="Main navigation"><a class="desktop-link" href="#admin-app" data-scroll="admin-app">Admin app</a><a class="desktop-link" href="#playground-product" data-scroll="playground-product">Playground</a><a class="desktop-link" href="#auto-router" data-scroll="auto-router">Auto router</a><a class="desktop-link" href="#/docs">Docs</a><a class="desktop-link" href="#/pricing">Pricing</a><a class="desktop-link" href="#/roadmap">Roadmap</a><a class="btn small" href="#/console">Open console ${icon('arrow')}</a></nav></header><main id="main"><section class="hero"><div><div class="eyebrow">THE GATEWAY. THE PLAYGROUND. THE ADMIN APP.</div><h1 class="serif">One gateway.<br>Every request,<br><span>understood.</span></h1><p class="hero-copy">One API to route your models. A playground to explore every response. An admin app to understand traffic, cost and provider health—all on your infrastructure.</p><div class="hero-actions"><a class="btn primary" href="#/chat">Try the playground ${icon('arrow')}</a><a class="btn" href="#/console">Explore the admin app ${icon('grid')}</a></div><p class="hero-meta">${icon('check')} Open source <span>·</span> Self-hostable <span>·</span> MIT licensed</p></div>${suiteHero()}</section><div class="hero-proof"><span>${icon('layers')} One Open Responses contract</span><span>${icon('server')} Deploy on your infrastructure</span><span>${icon('coin')} Cost on every response</span><span>${icon('route')} Routing with context</span></div><div class="provider-row"><span class="eyebrow">ONE INTERFACE.<br>YOUR PROVIDERS.</span><span class="provider-name">OpenAI</span><span class="provider-name">ANTHROPIC</span><span class="provider-name">Google</span><span class="provider-name">Mistral</span><span class="provider-name">Ollama</span><span class="provider-name">AWS Bedrock</span></div>${productShowcases()}${autoLanding()}<section class="section" id="product"><div class="section-title"><div><span class="eyebrow">04 / THE API</span><h2>Familiar in.<br>More visibility out.</h2></div><p>Send a request using the Open Responses API. Aura gives you the response, with the provider, latency and cost details you need to understand it.</p></div><div class="code-workbench"><div class="code-side"><div class="code-header"><div class="code-tabs"><button data-code-tab="typescript" class="${state.codeTab==='typescript'?'active':''}">TypeScript</button><button data-code-tab="python" class="${state.codeTab==='python'?'active':''}">Python</button></div><button class="icon-button" id="copy-code" aria-label="Copy request code">${icon('copy')}</button></div><pre id="request-code">${esc(codeSample())}</pre></div><div class="code-side"><div class="code-header"><span class="eyebrow">ILLUSTRATIVE RESPONSE</span>${statusBadge('Completed')}</div><pre>{
  "model": "gpt-5.4-mini",
  "usage": {
    "input_tokens": <span class="code-purple">1240</span>,
    "output_tokens": <span class="code-purple">310</span>,
    "cost_usd": <span class="code-purple">0.0032</span>
  },
  "metadata": {
    "aura": { "provider": <span class="code-purple">"openai"</span> }
  }
}</pre></div></div></section><section class="bottom-cta"><div><h2>Make a request.<br>See the whole picture.</h2><p>Explore a response in the playground, then follow it into the admin app.</p></div><div class="suite-final-actions"><button class="btn primary" data-showcase-chat>Try a sample request ${icon('arrow')}</button><a class="btn" href="#/console">Explore admin app ${icon('grid')}</a><button class="text-button" data-quickstart>Self-host Aura ${icon('code')}</button></div></section></main><footer class="site-footer"><span>Aura LLM Gateway <span class="dim">/ by Umai Technologies</span></span><div><span>Interactive design concept</span><a href="https://www.aura-llm.dev/" target="_blank" rel="noopener">Current website ↗</a><a href="https://github.com/UmaiTech/aura-llm-gateway" target="_blank" rel="noopener">GitHub ↗</a></div></footer></div>`;$$('[data-hero-tab]').forEach(b=>b.onclick=()=>{state.heroTab=b.dataset.heroTab;const tab=state.heroTab;$$('[data-hero-tab]').forEach(a=>{a.classList.toggle('active',a.dataset.heroTab===tab);a.setAttribute('aria-selected',a.dataset.heroTab===tab)});$('#hero-inspector').innerHTML=heroContent();bindCommon()});$$('[data-code-tab]').forEach(b=>b.onclick=()=>{state.codeTab=b.dataset.codeTab;$$('[data-code-tab]').forEach(a=>a.classList.toggle('active',a.dataset.codeTab===state.codeTab));$('#request-code').textContent=codeSample()});$('#copy-code').onclick=()=>copyText(codeSample());$$('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth'})});}
function heroContent(){if(state.heroTab==='raw')return `<pre style="font-size:11px">${esc(JSON.stringify({usage:{input_tokens:1240,output_tokens:310,cost_usd:.0032},metadata:{aura:{provider:'openai',latency_ms:842}}},null,2))}</pre>`;if(state.heroTab==='routing')return `<div class="kv"><span>Strategy</span><span class="mono accent">Balanced</span></div><div class="kv"><span>Selected provider</span><span>OpenAI</span></div><div class="kv"><span>Fallback</span><span class="status">Available</span></div><p class="tiny dim" style="margin-top:15px">Illustrative routing decision for this sample.</p>`;return `<dl class="detail-grid"><div class="detail-item"><dt>Total duration</dt><dd>842 <small>ms</small></dd></div><div class="detail-item"><dt>Request cost</dt><dd>$0.0032</dd></div><div class="detail-item"><dt>Input tokens</dt><dd>1,240</dd></div><div class="detail-item"><dt>Output tokens</dt><dd>310</dd></div></dl>`}
function codeSample(){return state.codeTab==='python'?`from aura import AuraClient\n\nclient = AuraClient(\n    base_url="http://localhost:8080"\n)\n\nresponse = client.responses.create(\n    model="gpt-5.4-mini",\n    input="Explain this payload."\n)\n\nprint(response.output_text)`:`import { AuraClient, outputText } from 'aura-llm'\n\nconst client = new AuraClient({\n  baseUrl: 'http://localhost:8080'\n})\n\nconst response = await client.responses.create({\n  model: 'gpt-5.4-mini',\n  input: 'Explain this payload.'\n})\n\nconsole.log(outputText(response))`}
const navItems=[['overview','grid','Overview'],['requests','activity','Requests'],['providers','server','Providers'],['routing','route','Routing'],['usage','chart','Usage'],['access','key','Access'],['settings','settings','Settings']];
function adminSidebar(page){return `<aside class="sidebar"><a class="brand" href="#/">${brand()}</a><div class="workspace"><span class="workspace-avatar">a</span><div>Acme workspace<small class="dim" style="display:block;font-size:9px">Production · sample</small></div></div><div class="sidebar-label">WORKSPACE</div><nav class="side-nav" aria-label="Console">${navItems.map(([id,ic,name])=>`<a href="#/console${id==='overview'?'':'/'+id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${name}${id==='requests'?`<span class="count">${state.requests.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-label">BUILD</div><nav class="side-nav"><a href="#/chat">${icon('chat')}Playground${icon('external')}</a><button data-quickstart>${icon('book')}Quickstart</button></nav><div class="sidebar-bottom"><div class="sidebar-note"><span><span class="mini-dot"></span> Demo environment</span><span>v0.1</span></div></div></aside>`}
function appTop(label){return `<header class="app-top"><div class="breadcrumb"><button class="icon-button mobile-menu" data-mobile-menu aria-label="Open navigation">${icon('menu')}</button>Acme <span>/</span> Production <span>/</span> ${esc(label)}</div><div class="top-actions"><span class="status">Demo connected</span><a class="btn small" href="#/chat">${icon('chat')} Playground</a><span class="avatar" title="Sample user">ME</span></div></header>`}
function renderAdmin(page){const label=navItems.find(x=>x[0]===page)?.[2]||'Overview';$('#app').innerHTML=`<div class="app-shell">${adminSidebar(page)}<div class="mobile-scrim"></div><main class="app-main" id="main">${appTop(label)}<div class="admin-content" id="admin-content">${page==='requests'?requestsPage():page==='providers'?providersPage():page==='routing'?routingPage():page==='usage'?usagePage():page==='access'?accessPage():page==='settings'?settingsPage():overviewPage()}</div></main></div>`;bindAdmin(page);}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="toolbar">${actions}</div></div>`}
function rangeSelect(){return `<select class="select" id="time-range" aria-label="Time range">${[['24h','Last 24 hours'],['7d','Last 7 days'],['30d','Last 30 days']].map(([v,l])=>`<option value="${v}" ${state.range===v?'selected':''}>${l}</option>`).join('')}</select>`}
function metrics(){const v=state.range==='24h'?['24,810','$18.42','842 ms','99.7%']:state.range==='7d'?['168,392','$126.70','867 ms','99.6%']:['721,046','$549.16','854 ms','99.8%'];const captions=['requests in selected period','estimated provider spend','end-to-end duration','completed / total requests'];return `<section class="metrics" aria-label="Gateway metrics">${['Requests','Total cost','Average latency','Success rate'].map((n,i)=>`<div class="metric"><div class="metric-top">${n}${icon(['activity','coin','clock','check'][i])}</div><div class="metric-value">${state.dataState==='empty'?(i===0?'0':'—'):v[i]}</div><div class="metric-caption">${captions[i]}</div></div>`).join('')}</section>`}
function chart(){const weights=state.range==='24h'?[240,180,160,110,120,170,260,420,390,610,740,680,840,990,860,780,920,670,520,620,440,340,280,230]:state.range==='7d'?[630,770,690,910,740,860,920]:Array.from({length:30},(_,i)=>[480,620,590,760,680,840,730,980,790,920,870,1020][i%12]);const total=state.range==='24h'?24810:state.range==='7d'?168392:721046;const sum=weights.reduce((a,b)=>a+b,0);const values=weights.map(v=>Math.round(v/sum*total));values[values.length-1]+=total-values.reduce((a,b)=>a+b,0);const ymax=Math.ceil(Math.max(...values)/4000)*4000;const labels=state.range==='24h'?['00:00','04:00','08:00','12:00','16:00','20:00']:state.range==='7d'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['Week 1','Week 2','Week 3','Week 4'];let width=550,height=190,bw=470/values.length;return `<div class="chart-wrap"><div class="chart-tooltip" id="chart-tooltip">${state.range==='24h'?'Hourly':'Daily'} sample volume</div><svg viewBox="0 0 550 220" role="img" aria-label="Illustrative request volume for ${state.range}">${[0,1,2,3].map(i=>`<line x1="40" y1="${15+i*53}" x2="540" y2="${15+i*53}" stroke="var(--border)" stroke-dasharray="3 5"/><text x="0" y="${19+i*53}" fill="var(--dim)" font-size="9" font-family="monospace">${[ymax,Math.round(ymax*2/3),Math.round(ymax/3),0][i].toLocaleString('en-US')}</text>`).join('')}${values.map((v,i)=>`<rect class="chart-bar" data-value="${v}" tabindex="0" aria-label="Sample bucket ${i+1}: ${v} requests" x="${45+i*bw}" y="${174-v/ymax*155}" width="${Math.max(6,bw-7)}" height="${v/ymax*155}" rx="2" fill="var(--accent)" opacity="${i===13?.95:.56}"/>`).join('')}${labels.map((l,i)=>`<text x="${46+i*475/Math.max(1,labels.length-1)}" y="204" fill="var(--dim)" font-size="9" font-family="monospace" text-anchor="${i===labels.length-1?'end':'start'}">${l}</text>`).join('')}</svg></div>`}
function healthPanel(){return `<section class="panel"><div class="panel-heading"><h2>Provider health</h2><a class="view-all" href="#/console/providers">Manage ${icon('arrow')}</a></div>${['OpenAI','Anthropic','Google'].map((n,i)=>`<div class="health-row"><div class="health-name"><span class="provider-badge">${n[0]}</span><div>${n}<div class="health-latency">${state.providers[n]?[`${842} ms`,`1.21 s`,`2.51 s`][i]:'Not receiving requests'}</div></div></div>${state.providers[n]?statusBadge(i===2?'Degraded':'Healthy'):'<span class="status neutral">Disabled</span>'}</div>`).join('')}<div class="health-small-note">Sample snapshot · provider status is illustrative</div></section>`}
function requestTable(reqs,limit){const rs=limit?reqs.slice(0,limit):reqs;if(!rs.length)return `<div class="empty">${icon('search')}<h3>No requests found</h3><p>Try another filter, or send a sample in the playground.</p></div>`;return `<div class="table-wrap"><table><thead><tr><th>Request</th><th>Provider / model</th><th>Duration</th><th>Cost</th><th>Status</th><th>Time <span class="dim">UTC</span></th><th></th></tr></thead><tbody>${rs.map(r=>`<tr class="clickable" data-open-request="${r.id}"><td><button class="text-button request-id" data-open-request="${r.id}" aria-label="Inspect ${r.id}">${r.id}</button></td><td>${esc(r.provider)}<div class="mono dim" style="font-size:9px;margin-top:3px">${esc(r.model)}</div></td><td class="mono">${duration(r.latency)}</td><td class="mono">${cost(r.cost)}</td><td>${statusBadge(r.status)}</td><td class="mono dim">${r.time}</td><td class="dim">${icon('chevron')}</td></tr>`).join('')}</tbody></table></div>`}
function overviewPage(){const partial=state.dataState==='partial',empty=state.dataState==='empty';return `${pageHead('Gateway overview','A clear view of your traffic, cost and provider health.',`<span class="ui-state">${icon('clock')} Updated just now</span>${rangeSelect()}<button class="icon-button" id="refresh-data" aria-label="Refresh sample data">${icon('refresh')}</button>`)}${partial?`<div class="notice partial-banner">${icon('alert')}Provider health is unavailable. Other panels show the selected period.<button class="text-button" id="retry-data">Retry</button></div>`:''}${metrics()}<div class="chart-grid"><section class="panel"><div class="panel-heading"><div><h2>Request volume</h2><p>${state.range==='24h'?'Hourly':'Daily'} sample requests · UTC</p></div><span class="chart-legend">Requests</span></div>${empty?'<div class="empty"><h3>No traffic in this period</h3><p>New requests will appear here.</p></div>':chart()}</section>${partial?`<section class="panel"><div class="panel-heading"><h2>Provider health</h2><span class="status warning">Unavailable</span></div><div class="empty">${icon('alert')}<h3>We couldn’t load health data</h3><p>Last sample update: 2 minutes ago.</p><button class="btn small" id="retry-health" style="margin-top:18px">Retry</button></div></section>`:healthPanel()}</div><section class="panel"><div class="panel-heading"><h2>Recent requests</h2><a class="view-all" href="#/console/requests">View all requests ${icon('arrow')}</a></div>${requestTable(empty?[]:state.requests,5)}<div class="table-footer"><span>Illustrative recent rows · click a request to inspect</span><span>${empty?0:Math.min(state.requests.length,5)} requests</span></div></section><div class="request-footer">Demo metrics use fixed fixtures for each time range. Playground requests appear in the recent-request list.</div>`}
function filteredRequests(){const q=state.filter.toLowerCase();return state.requests.filter(r=>(state.provider==='all'||r.provider===state.provider)&&(state.status==='all'||r.status===state.status)&&(!q||(r.id+' '+r.model+' '+r.provider).toLowerCase().includes(q)))}
function requestsPage(){return `${pageHead('Requests','Follow any request from provider selection to its response.',`<button class="btn small" id="export-requests">${icon('download')} Export CSV</button>`)}<div class="filter-bar"><label class="search-field">${icon('search')}<input id="request-search" placeholder="Search requests or models…" aria-label="Search requests" value="${esc(state.filter)}"></label><select class="select" id="provider-filter" aria-label="Filter provider"><option value="all">All providers</option>${['OpenAI','Anthropic','Google'].map(p=>`<option ${state.provider===p?'selected':''}>${p}</option>`).join('')}</select><select class="select" id="status-filter" aria-label="Filter status"><option value="all">All statuses</option>${['Completed','Failed','Stopped'].map(p=>`<option ${state.status===p?'selected':''}>${p}</option>`).join('')}</select><button class="btn small ghost" id="clear-filters">Clear</button></div><section class="panel" id="requests-table">${requestTable(filteredRequests())}<div class="table-footer"><span>${filteredRequests().length} matching requests</span><span>Sample data · UTC</span></div></section>`}
function providersPage(){return `${pageHead('Providers','Manage the providers available to your sample workspace.')}<div class="notice">${icon('shield')}Demo connections only. No provider credentials are stored or requested.</div><div class="provider-cards">${['OpenAI','Anthropic','Google'].map((n,i)=>`<section class="panel provider-card"><header><span class="provider-badge">${n[0]}</span><button role="switch" class="toggle" aria-label="Enable ${n}" aria-checked="${state.providers[n]}" data-provider-toggle="${n}"></button></header><h2>${n}</h2><p>${['Responses and reasoning models','Claude model family','Gemini model family'][i]}</p><div class="kv"><span>Connection</span>${state.providers[n]?statusBadge(i===2?'Degraded':'Healthy'):'<span class="status neutral">Disabled</span>'}</div><div class="kv"><span>Sample model</span><span class="mono tiny">${['gpt-5.4-mini','claude-sonnet-4-5','gemini-2.5-flash'][i]}</span></div><div class="kv"><span>Key</span><span class="mono dim">Demo · no credentials</span></div><button class="btn small" style="margin-top:20px;width:100%" data-provider-requests="${n}">View requests ${icon('arrow')}</button></section>`).join('')}</div>`}
const strategies=[['balanced','Balanced','Neutral complexity offset.'],['cost','Cost','Shift the score toward cheaper tiers.'],['quality','Quality','Shift borderline requests toward stronger tiers.']];
let pendingRouting=state.routing;
function usagePage(){const factor=state.range==='7d'?6.879:state.range==='30d'?29.813:1;return `${pageHead('Usage & cost','Read token usage and provider spend in the same context.',rangeSelect())}${metrics()}<div class="usage-grid"><section class="panel form-panel"><h2>Cost by provider</h2><p>Illustrative breakdown for the selected period.</p>${[['OpenAI',state.range==='24h'?8.64:state.range==='7d'?59.43:257.58,47],['Anthropic',state.range==='24h'?7.94:state.range==='7d'?54.62:236.72,43],['Google',state.range==='24h'?1.84:state.range==='7d'?12.65:54.86,10]].map(([n,c,p])=>`<div class="usage-provider"><span>${n}</span><div class="usage-bar"><span style="width:${p}%"></span></div><em>$${c.toFixed(2)}</em></div>`).join('')}</section><section class="panel form-panel"><h2>Reading your costs</h2><p>Request-level amounts are shown in USD. The prototype contains fixed sample values.</p><div class="kv"><span>Input tokens</span><span class="mono">${Math.round(1450830*factor).toLocaleString()}</span></div><div class="kv"><span>Output tokens</span><span class="mono">${Math.round(372840*factor).toLocaleString()}</span></div><div class="kv"><span>Cached tokens</span><span class="mono">${Math.round(128420*factor).toLocaleString()}</span></div><a class="btn small" href="#/console/requests" style="margin-top:24px">Inspect request costs ${icon('arrow')}</a></section></div>`}
function accessPage(){return `${pageHead('Access','A sample of how workspace access and keys could look.')}<div class="notice">${icon('shield')}Read-only design sample. No real credentials or permissions are managed here.</div><section class="panel"><div class="panel-heading"><h2>Project API keys</h2><span class="eyebrow">SAMPLE RECORDS</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Identifier</th><th>Scope</th><th>Status</th></tr></thead><tbody><tr><td>Production application</td><td class="mono dim">aura_demo_••••_8f12</td><td>Responses · read usage</td><td>${statusBadge('Active')}</td></tr><tr><td>Development</td><td class="mono dim">aura_demo_••••_2c81</td><td>Responses</td><td>${statusBadge('Active')}</td></tr></tbody></table></div></section><section class="panel" style="margin-top:24px"><div class="panel-heading"><h2>Workspace members</h2></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Project</th></tr></thead><tbody><tr><td>Sample owner</td><td>Owner</td><td>All projects</td></tr><tr><td>Sample engineer</td><td>Developer</td><td>Production</td></tr></tbody></table></div></section>`}
function settingsPage(){return `${pageHead('Prototype settings','Explore the design under different conditions.')}<section class="panel form-panel"><h2>Appearance</h2><p>One set of design tokens across the landing page, console and playground.</p><div class="theme-options"><button class="btn ${state.theme==='dark'?'primary':''}" data-set-theme="dark">${icon('moon')}Dark</button><button class="btn ${state.theme==='light'?'primary':''}" data-set-theme="light">${icon('sun')}Light</button></div><div class="form-row" style="margin-top:28px"><label for="data-state">Dashboard data state<small>Preview empty and partial-error states on the overview page.</small></label><select class="select" id="data-state">${[['normal','Normal'],['empty','Empty'],['partial','Partial error']].map(([v,l])=>`<option value="${v}" ${state.dataState===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-row"><label>Reset prototype<small>Restore preferences and remove this session’s sample requests.</small></label><button class="btn small" data-reset>Reset demo</button></div><div class="form-actions"><a class="btn primary" href="#/console">Preview overview ${icon('arrow')}</a></div></section>`}
function bindAdmin(page){$('#time-range')?.addEventListener('change',e=>{state.range=e.target.value;renderAdmin(page);bindCommon()});const refresh=()=>{toast('Sample snapshot refreshed');state.dataState='normal';renderAdmin(page);bindCommon()};$('#refresh-data')?.addEventListener('click',refresh);$('#retry-data')?.addEventListener('click',refresh);$('#retry-health')?.addEventListener('click',refresh);$$('.chart-bar').forEach(b=>{const f=()=>$('#chart-tooltip').textContent=Number(b.dataset.value).toLocaleString()+' sample requests';b.addEventListener('mouseenter',f);b.addEventListener('focus',f)});
function updateTable(){const rs=filteredRequests();$('#requests-table').innerHTML=requestTable(rs)+`<div class="table-footer"><span>${rs.length} matching requests</span><span>Sample data · UTC</span></div>`;bindCommon()}
$('#request-search')?.addEventListener('input',e=>{state.filter=e.target.value;updateTable()});$('#provider-filter')?.addEventListener('change',e=>{state.provider=e.target.value;updateTable()});$('#status-filter')?.addEventListener('change',e=>{state.status=e.target.value;updateTable()});$('#clear-filters')?.addEventListener('click',()=>{state.filter='';state.provider='all';state.status='all';renderAdmin(page);bindCommon()});$('#export-requests')?.addEventListener('click',()=>{const content='request,provider,model,duration_ms,cost_usd,status,time_utc\n'+filteredRequests().map(r=>[r.id,r.provider,r.model,r.latency,r.cost,r.status,r.time].join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:'text/csv'}));a.download='aura-sample-requests.csv';a.click();URL.revokeObjectURL(a.href);toast('Sample requests exported')});
$$('[data-provider-toggle]').forEach(b=>b.onclick=()=>{let n=b.dataset.providerToggle;state.providers[n]=!state.providers[n];persist();renderAdmin('providers');bindCommon();toast(n+(state.providers[n]?' enabled':' disabled')+' for this demo')});$$('[data-provider-requests]').forEach(b=>b.onclick=()=>{state.provider=b.dataset.providerRequests;state.filter='';state.status='all';goto('console/requests')});$$('[data-strategy]').forEach(b=>b.onclick=()=>{pendingRouting=b.dataset.strategy;$$('[data-strategy]').forEach(x=>{let active=x.dataset.strategy===pendingRouting;x.classList.toggle('selected',active);x.setAttribute('aria-pressed',active);x.querySelector('h3').innerHTML=strategies.find(s=>s[0]===x.dataset.strategy)[1]+(active?icon('check'):'')})});$('#fallback-toggle')?.addEventListener('click',e=>{const b=e.currentTarget;b.setAttribute('aria-checked',b.getAttribute('aria-checked')!=='true')});$('#save-routing')?.addEventListener('click',()=>{state.routing=pendingRouting;state.fallback=$('#fallback-toggle').getAttribute('aria-checked')==='true';persist();toast('Routing settings saved for simulated requests')});$('#routing-cancel')?.addEventListener('click',()=>{renderAdmin('routing');bindCommon();toast('Unsaved changes discarded')});$$('[data-set-theme]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.setTheme;persist();applyTheme();render()});$('#data-state')?.addEventListener('change',e=>{state.dataState=e.target.value;toast('Overview state changed to '+e.target.selectedOptions[0].textContent)});}
let overlayFocus=null;function showOverlay(title,subtitle,body,bottom='Prototype data only. No external requests are made.'){overlayFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="drawer-backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-heading"><div><h2 id="drawer-title">${title}</h2><p>${subtitle}</p></div><button class="icon-button" id="close-drawer" aria-label="Close details">${icon('close')}</button></div>${body}<div class="drawer-bottom">${bottom}</div></section></div>`;$('#close-drawer').onclick=closeOverlay;$('.drawer-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeOverlay()};$('#close-drawer').focus();bindCommon();}
function closeOverlay(){$('#overlay-root').innerHTML='';overlayFocus?.focus?.();overlayFocus=null;}
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();$('.sidebar')?.classList.remove('open');$('.mobile-scrim')?.classList.remove('show')}if(e.key==='Tab'&&$('.drawer')){const els=[...$('.drawer').querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(e=>!e.disabled);const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function openRequest(id,tab='overview'){let r=state.requests.find(x=>x.id===id)||state.activeRequest||seedRequests[0];showOverlay('Request details',esc(r.id),inspectorTabs(tab)+`<div class="drawer-body" id="drawer-data">${detailContent(r,tab)}</div>`);$$('[data-detail-tab]').forEach(b=>b.onclick=()=>openRequest(r.id,b.dataset.detailTab));}
function openQuickstart(){showOverlay('Quickstart','SELF-HOST AURA',`<div class="drawer-body"><p class="muted" style="margin-bottom:25px;font-size:13px">Connect your app to a locally running Aura gateway. This is an example integration, not a live connection.</p><div class="code-header"><span class="eyebrow">INSTALL TYPESCRIPT SDK</span><button class="icon-button" data-copy="npm install aura-llm" aria-label="Copy install command">${icon('copy')}</button></div><pre class="raw-box">npm install aura-llm</pre><div class="code-header" style="margin-top:30px"><span class="eyebrow">SEND A REQUEST</span></div><pre class="raw-box">${esc(codeSample())}</pre><p class="tiny muted" style="margin:22px 0">Configure provider credentials and gateway authentication following the official documentation.</p><a href="https://github.com/UmaiTech/aura-llm-gateway" target="_blank" rel="noopener" class="btn">Open repository ${icon('external')}</a></div>`,'Examples reflect the reviewed repository. Check its documentation for deployment setup.');}
const prompts=[['Inspect a response','See cost, tokens and provider details.','Explain what Aura adds to this LLM response.'],['Explore a routing decision','Follow a request to its selected provider.','Show me how this request is routed.'],['Try structured input','Explore a sample compression comparison.','Summarize this structured payload: [{"name":"alpha","status":"active"},{"name":"beta","status":"active"}].']];
function chatSidebar(){return `<aside class="sidebar"><a class="brand" href="#/">${brand()}</a><button class="btn chat-sidebar-new" id="new-session">${icon('plus')} New session</button><div class="sidebar-label">RECENT SESSIONS</div><div class="chat-history">${state.chatStarted?`<button class="active" id="current-session">${esc(state.sessionName)}</button>`:''}<button id="sample-session">Response inspection <span class="dim">· sample</span></button>${state.savedSession?'<button id="previous-session">Previous demo session</button>':''}</div><div class="chat-sidebar-bottom"><a class="btn small ghost" href="#/console">${icon('grid')} Open console ${icon('arrow')}</a><p>Local design prototype.<br>Responses and telemetry are simulated.</p></div><div class="sidebar-note"><span><span class="mini-dot"></span> Demo gateway</span><span>Connected</span></div></aside>`}
function renderChat(){$('#app').innerHTML=`<div class="app-shell chat-shell">${chatSidebar()}<div class="mobile-scrim"></div><main class="chat-main" id="main"><header class="app-top"><div class="breadcrumb"><button class="icon-button mobile-menu" data-mobile-menu aria-label="Open navigation">${icon('menu')}</button><span class="chat-top-label" style="color:var(--text)">Playground</span><select id="chat-model" class="select model-select" aria-label="Select model">${['auto','auto:cost','auto:balanced','auto:quality',...Object.keys(modelInfo)].map(m=>`<option ${state.model===m?'selected':''}>${m}</option>`).join('')}</select></div><div class="top-actions"><a class="session-cost accent" href="#/console/routing">Auto-router policy</a><button class="icon-button" data-request-settings aria-label="Request settings" title="Request settings">${icon('sliders')}</button><button class="icon-button" id="inspect-latest" aria-label="Inspect latest request" title="Inspect latest request">${icon('panel')}</button></div></header><div class="chat-workspace"><section class="conversation" aria-label="Conversation"><div class="chat-scroll" id="chat-scroll"><div class="message-container" id="messages">${state.chatStarted?messagesHTML():welcomeHTML()}</div></div><form class="composer-wrap" id="chat-form"><div class="composer"><textarea id="chat-input" rows="2" aria-label="Message" placeholder="Send a request through Aura…" ${state.streaming?'disabled':''}></textarea><div class="composer-bottom"><div><button type="button" class="icon-button" data-request-settings aria-label="Configure request">${icon('sliders')}</button><span class="composer-tag">${icon('code')} ${state.compression?'Compression on':'Request settings'}</span></div><button class="btn primary small" id="send-message" type="${state.streaming?'button':'submit'}">${icon(state.streaming?'stop':'send')} ${state.streaming?'Stop':'Send'}</button></div></div><p class="composer-note">Simulated responses · no API calls or credentials required</p></form></section><aside class="inline-inspector" aria-label="Request inspector"><div class="panel-heading"><h2>Request details</h2>${icon('panel')}</div>${inspectorTabs(state.inspectorTab,'inline')}<div class="inspector-content" id="inline-content">${state.activeRequest?detailContent(state.activeRequest,state.inspectorTab):`<div class="inspector-empty">${icon('activity')}<h3>Every request has a story.</h3><p>Send a sample request to see its provider, cost and routing details here.</p><button class="text-button" id="load-sample">Inspect a sample ${icon('arrow')}</button></div>`}</div><div class="drawer-bottom">Illustrative telemetry. Not measured performance.</div></aside></div></main></div>`;bindChat();bindCommon();if(state.chatStarted)scrollChat();}
function welcomeHTML(){return `<div class="chat-welcome"><img class="welcome-brand" src="assets/aura-mark-${state.theme==='dark'?'violet':'ink'}.svg" alt="Aura"><div class="eyebrow" style="margin-bottom:15px">AURA PLAYGROUND</div><h1>Explore what’s behind<br>the response.</h1><p>Start with a sample. See which provider responds, what the request costs, and how it gets there.</p>${prompts.map(([title,desc,prompt],i)=>`<button class="prompt-option" data-prompt="${esc(prompt)}"><span>0${i+1}</span><span><strong>${title}</strong><small>${desc}</small></span>${icon('arrow')}</button>`).join('')}<div class="welcome-note">Demo workspace. Your prompts stay in this browser tab.</div></div>`}
function messagesHTML(){return state.messages.map((m,i)=>`<article class="message ${m.role}"><div class="message-role">${m.role==='user'?'<span class="avatar">ME</span><span>You</span>':`<img src="assets/aura-mark-${state.theme==='dark'?'violet':'ink'}.svg" alt="Aura"><span>Aura <span class="dim">/ ${esc(m.model||state.model)}</span></span>`}</div><div class="message-text ${state.streaming&&i===state.messages.length-1?'stream-dot':''}" ${m.role==='assistant'?'aria-live="off"':''}>${esc(m.text)}</div>${m.request?`<div class="message-meta"><span>${duration(m.request.latency)}</span><span>${cost(m.request.cost)}</span><span>${(m.request.input+m.request.output).toLocaleString()} tokens</span><button class="text-button" data-inspect-message="${m.request.id}">Inspect request ${icon('arrow')}</button></div>`:''}</article>`).join('')}
function scrollChat(){const el=$('#chat-scroll');if(el)el.scrollTop=el.scrollHeight;}
function bindChat(){$('#chat-model').onchange=e=>{state.model=e.target.value;persist();toast('Model set to '+state.model)};$('#new-session').onclick=()=>{if(state.streaming)stopStream();if(state.messages.length)state.savedSession={messages:[...state.messages],request:state.activeRequest,name:state.sessionName};state.messages=[];state.chatStarted=false;state.activeRequest=null;state.sessionName='Untitled session';renderChat()};$('#sample-session').onclick=loadSample;$('#load-sample')?.addEventListener('click',loadSample);$('#previous-session')?.addEventListener('click',()=>{if(state.streaming)stopStream();const prev=state.savedSession;state.messages=[...prev.messages];state.activeRequest=prev.request;state.sessionName=prev.name;state.chatStarted=true;renderChat()});$('#current-session')?.addEventListener('click',()=>toast('You’re viewing this session'));$$('[data-prompt]').forEach(b=>b.onclick=()=>sendMessage(b.dataset.prompt));$('#chat-form').onsubmit=e=>{e.preventDefault();const input=$('#chat-input').value.trim();if(input)sendMessage(input);else $('#chat-input').focus()};$('#chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit()}};if(state.streaming)$('#send-message').onclick=stopStream;$('#inspect-latest').onclick=()=>openRequest(state.activeRequest?.id||seedRequests[0].id);$$('[data-inline-tab]').forEach(b=>b.onclick=()=>{state.inspectorTab=b.dataset.inlineTab;updateInline()});bindMessageInspect();}
function bindMessageInspect(){$$('[data-inspect-message]').forEach(b=>b.onclick=()=>{state.activeRequest=state.requests.find(r=>r.id===b.dataset.inspectMessage);state.inspectorTab='overview';if(window.innerWidth<=930)openRequest(state.activeRequest.id);else updateInline()});}
function updateInline(){if(!$('#inline-content'))return;$('#inline-content').innerHTML=state.activeRequest?detailContent(state.activeRequest,state.inspectorTab):'<div class="inspector-empty">Send a sample request to populate these details.</div>';$$('[data-inline-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.inlineTab===state.inspectorTab);b.setAttribute('aria-selected',b.dataset.inlineTab===state.inspectorTab)});bindCommon()}
function loadSample(){if(state.streaming)stopStream();const r={...seedRequests[0]};state.messages=[{role:'user',text:prompts[0][2]},{role:'assistant',text:'Aura sits between your application and the model provider. This sample response includes the selected provider, token usage and estimated cost, so you can inspect the request without switching tools.\n\nOpen Request details to explore the overview, routing decision and raw response. The values here are illustrative, not a live measurement.',model:r.model,request:r}];state.activeRequest=r;state.chatStarted=true;state.sessionName='Response inspection';renderChat()}
function answerFor(prompt,model){const lower=prompt.toLowerCase(),p=modelInfo[model].provider;if(lower.includes('rout'))return `This pinned-model demo selected ${p} using the ${strategies.find(s=>s[0]===state.routing)[1].toLowerCase()} strategy.\n\n1. Apply the workspace’s model preferences.\n2. Check whether the selected provider is enabled.\n3. ${state.fallback?'Keep another enabled provider available as a fallback.':'Use only the selected provider.'}\n\nInspect the Routing tab to follow this illustrative decision. You can change the strategy in Console → Routing and send another sample.`;if(lower.includes('payload')||lower.includes('compress')||lower.includes('json'))return `The sample payload contains two active records, alpha and beta. Both share the same structure, which makes this a useful example for exploring structured-input compression.\n\n${state.compression?'Compression is enabled. The inspector shows a fixed 35% reduction for this demonstration, not a measured result. Actual savings depend on the payload and compression strategy.':'Compression is currently off. Enable it in Request settings and send this example again to see the simulated comparison.'}\n\nProvider: ${p}. Open the request inspector to compare tokens and cost.`;if(lower.includes('aura')||lower.includes('response')||lower.includes('cost'))return `Aura gives your application a common interface across model providers. Alongside the response, you can inspect which provider handled it, how many tokens were used and the estimated cost.\n\nThis sample uses ${model}. The panel on the right keeps the request details next to the conversation, and the same request appears in the Console.\n\nThis is a simulated product demonstration. No LLM provider was contacted.`;return `This prototype received your message and is demonstrating the streaming experience with ${p}.\n\nIn the connected product, ${model} would answer your prompt here. This demo uses a fixed local response so you can explore the interface without an API key.\n\nTry inspecting this request, changing the model, or turning on compression in Request settings. You can also find this sample in Console → Requests.`;}
function sendMessage(prompt){if(state.streaming)return;const autoDecision=decisionForPrompt(prompt);const model=autoDecision.shadow?state.model:autoDecision.selected;if(!model||!state.providers[modelInfo[model]?.provider]){toast('No eligible model for this demo. Review tier bounds and enabled providers.');return;}const info=modelInfo[model];const r={id:'req_demo_'+String(state.requests.length-7).padStart(3,'0'),provider:info.provider,model,input:state.compression?806:1240,output:info.output,cost:state.compression?Number((info.cost*.78).toFixed(4)):info.cost,latency:info.latency,status:'Completed',time:new Date().toISOString().slice(11,19),compression:state.compression,routing:state.routing,autoDecision};state.chatStarted=true;state.sessionName=prompt.slice(0,30)+(prompt.length>30?'…':'');state.messages.push({role:'user',text:prompt},{role:'assistant',text:'',model});state.streaming=true;const answer=autoDecision.shadow?`This sample keeps your pinned model, ${model}. The shadow decision suggests ${autoDecision.selected||'no eligible alternative'}; it does not change the model answering.\n\n${answerFor(prompt,model)}`:`This simulated request was classified as ${autoDecision.classified_tier} and routed to the ${autoDecision.tier} tier.\n\nSelected: ${model}\nMode: ${autoDecision.mode}\nReason: ${autoDecision.reason}\n\nThis is an illustrative fixture, not Aura’s production classifier. Open Routing to inspect the candidates, or Raw JSON for metadata.aura.routing.`;let position=0;renderChat();state.streamTimer=setInterval(()=>{position=Math.min(position+14,answer.length);state.messages[state.messages.length-1].text=answer.slice(0,position);if(route()==='chat'){$('#messages').innerHTML=messagesHTML();scrollChat()}if(position>=answer.length){clearInterval(state.streamTimer);state.streaming=false;state.messages[state.messages.length-1].request=r;state.requests.unshift(r);state.activeRequest=r;if(route()==='chat'){renderChat();$('#chat-input')?.focus()}else if(route().startsWith('console'))render();toast('Sample response complete · request added to console')}},35)}
function stopStream(){if(!state.streaming)return;clearInterval(state.streamTimer);state.streaming=false;state.messages[state.messages.length-1].text+='\n\n[Stopped by you. This partial sample has no completed usage record.]';if(route()==='chat')renderChat();toast('Generation stopped')}
function openChatSettings(){showOverlay('Request settings','APPLIES TO THE NEXT SAMPLE',`<div class="drawer-body"><div class="settings-group"><label for="settings-model">Model</label><select id="settings-model">${['auto','auto:cost','auto:balanced','auto:quality',...Object.keys(modelInfo)].map(m=>`<option ${state.model===m?'selected':''}>${m}</option>`).join('')}</select></div><div class="form-row"><label>Compression<small>Simulate a smaller structured input payload.</small></label><button role="switch" class="toggle" id="compression-switch" aria-label="Compression" aria-checked="${state.compression}"></button></div><div class="form-row"><label>Validation<small>Record the validation preference for this demo.</small></label><button role="switch" class="toggle" id="validation-switch" aria-label="Validation" aria-checked="${state.validation}"></button></div><div class="form-row"><label>Routing strategy<small>Auto alias mode or local console default.</small></label><span class="tiny accent">${strategies.find(s=>s[0]===state.routing)[1]}</span></div><p class="tiny dim" style="margin-top:23px">Compression uses a fixed illustrative reduction. Validation is a UI preference only; this prototype does not assess output quality.</p><div class="form-actions"><button class="btn primary" id="save-chat-settings">Apply settings</button></div></div>`);['compression-switch','validation-switch'].forEach(id=>$('#'+id).onclick=e=>{let b=e.currentTarget;b.setAttribute('aria-checked',b.getAttribute('aria-checked')!=='true')});$('#save-chat-settings').onclick=()=>{state.model=$('#settings-model').value;state.compression=$('#compression-switch').getAttribute('aria-checked')==='true';state.validation=$('#validation-switch').getAttribute('aria-checked')==='true';persist();closeOverlay();if(route()==='chat')renderChat();toast('Settings applied to the next sample')};}
function resetDemo(){if(state.streaming)stopStream();state.requests=[...seedRequests];state.messages=[];state.chatStarted=false;state.activeRequest=null;state.savedSession=null;state.routing='balanced';state.fallback=true;state.providers={OpenAI:true,Anthropic:true,Google:true};state.compression=false;state.validation=false;state.model='auto';Object.assign(autoUI,{scenario:'rewrite',mode:'balanced',min:'simple',max:'reasoning',shadow:false});saveAuto();state.filter='';state.provider='all';state.status='all';state.dataState='normal';persist();render();toast('Prototype reset to its initial sample state')}


// Auto-router design extension. All scoring and prices below are illustrative.
let autoSaved={};try{autoSaved=JSON.parse(localStorage.getItem('aura-auto-v2')||'{}')}catch{}
const autoUI={scenario:'rewrite',mode:'balanced',min:'simple',max:'reasoning',shadow:false,...autoSaved};
if(!['balanced','cost','quality'].includes(state.routing))state.routing='balanced';
for(const c of AUTO_CATALOG)if(!modelInfo[c.model])modelInfo[c.model]={provider:c.provider,input:1240,output:310,cost:Number((c.price*.00155).toFixed(4)),latency:840};
function saveAuto(){try{localStorage.setItem('aura-auto-v2',JSON.stringify(autoUI))}catch{}}
function currentDecision(){return simulateAuto({...autoUI,providers:state.providers});}
function cleanDecision(d){const {fixture_candidates,fixture_signal,actual_model,error,...data}=d;return data;}
function modeButtons(){return `<div class="auto-modes" role="group" aria-label="Routing mode">${['cost','balanced','quality'].map(m=>`<button data-auto-mode="${m}" aria-pressed="${autoUI.mode===m}" class="${autoUI.mode===m?'active':''}">${m[0].toUpperCase()+m.slice(1)}</button>`).join('')}</div>`;}
function autoDecisionHTML(d,full=false){return `<div class="auto-decision"><div class="auto-result-top"><span class="eyebrow">${d.shadow?'SHADOW / NOT APPLIED':'AUTO / APPLIED IN DEMO'}</span><span class="status ${d.error?'error':''}">${d.error?'No eligible model':d.tier+' tier'}</span></div><h3 class="auto-model">${esc(d.selected||'No model selected')}</h3><p class="muted tiny">${esc(d.reason)}</p>${d.shadow?`<div class="notice">Pinned model answers: <strong>${esc(d.actual_model)}</strong>. Auto is a comparison only.</div>`:''}<div class="tier-track">${AUTO_TIERS.map(t=>`<span class="${d.tier===t?'active':''}">${t}</span>`).join('')}</div><dl class="detail-stack"><div><dt>Mode / score</dt><dd>${d.mode} / ${d.score.toFixed(2)}</dd></div><div><dt>Classified → final tier</dt><dd>${d.classified_tier} → ${d.tier}</dd></div><div><dt>Signal</dt><dd>${esc(d.fixture_signal)}</dd></div><div><dt>Constraints</dt><dd>${esc(d.hard_filters.join(', ')||'Configured providers')}</dd></div></dl>${full?`<div class="auto-candidates"><div class="code-header"><span class="eyebrow">CANDIDATES</span><span class="tiny dim">Fixture $ / 1M blended</span></div>${d.fixture_candidates.map(c=>`<div class="candidate ${c.model===d.selected?'selected':''}"><div><strong>${esc(c.model)}</strong><small>${c.tier} · ${esc(c.excluded||'Eligible')}</small></div><span>${c.model===d.selected?icon('check'):''}$${c.price.toFixed(2)}</span></div>`).join('')}</div>`:''}<p class="tiny dim" style="margin-top:18px">Illustrative scores, model candidates and prices. Tool scenarios stand in for a structured tools payload. No provider call or measured savings.</p></div>`;}
function autoWorkbench(full=false){return `<div class="auto-workbench"><div class="auto-controls"><div class="eyebrow">TRY A REQUEST SHAPE</div><div class="scenario-list">${AUTO_SCENARIOS.map((s,i)=>`<button data-auto-scenario="${s.id}" aria-pressed="${autoUI.scenario===s.id}" class="${autoUI.scenario===s.id?'active':''}"><span>0${i+1}</span><div>${s.name}<small>${s.signal}</small></div>${icon('arrow')}</button>`).join('')}</div><label class="auto-label">Cost / quality preference</label>${modeButtons()}<div class="form-row"><label>Shadow pinned model<small>Keep gpt-5.4-mini; preview the alternative.</small></label><button class="toggle" role="switch" aria-label="Shadow pinned model" data-auto-shadow aria-checked="${autoUI.shadow}"></button></div>${full?`<div class="auto-bounds"><label>Minimum tier<select data-auto-bound="min" aria-label="Minimum tier">${AUTO_TIERS.map(t=>`<option ${autoUI.min===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Maximum tier<select data-auto-bound="max" aria-label="Maximum tier">${AUTO_TIERS.map(t=>`<option ${autoUI.max===t?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="tiny dim">Bounds apply to the next demo request. Production scope belongs in request options or organization policy.</p>`:''}<pre class="raw-box auto-request">${esc(JSON.stringify({model:autoUI.shadow?'gpt-5.4-mini':'auto:'+autoUI.mode,input:AUTO_SCENARIOS.find(s=>s.id===autoUI.scenario).prompt,...(full?{routing:{min_tier:autoUI.min,max_tier:autoUI.max}}:{})},null,2))}</pre><button class="btn primary" data-try-auto>Try this in playground ${icon('arrow')}</button></div><div class="auto-output" aria-live="polite">${autoDecisionHTML(currentDecision(),full)}</div></div>`;}
function autoLanding(){return `<section class="section" id="auto-router"><div class="section-title"><div><span class="eyebrow">03 / AUTO MODEL ROUTING</span><h2>The right tier.<br>A reason you can read.</h2></div><div><p>Send <code>model: "auto"</code>. Aura scores request complexity and chooses an eligible model within the selected tier. Adjust the cost–quality balance; inspect what changed.</p><a href="#/docs/auto-routing" class="text-button" style="margin-top:18px">Read the auto-routing guide ${icon('arrow')}</a></div></div>${autoWorkbench()}<div class="auto-footnotes"><span>${icon('shield')} Capability and provider filters</span><span>${icon('route')} Tool-loop continuity</span><span>${icon('activity')} Shadow before switching traffic</span></div></section>`;}
function routingPage(){return `${pageHead('Auto router','Inspect a decision before changing traffic.',`<a class="btn small" href="#/docs/auto-routing">${icon('book')} Routing guide</a>`)}<div class="notice">${icon('alert')}Interactive dry-run concept. Changes here are browser-local demo preferences, not gateway settings.</div>${autoWorkbench(true)}<div class="auto-footnotes"><span>Production dry-run: <code>POST /admin/routing/score</code></span><span>Runtime defaults: Settings</span><span>Tenant policy: Organization</span></div><div class="form-actions"><button class="btn" data-auto-reset>Reset demo policy</button><button class="btn primary" data-auto-save>Use for next demo request</button></div>`;}
function bindAuto(){const redraw=()=>{saveAuto();render();};$$('[data-auto-mode]').forEach(b=>b.onclick=()=>{autoUI.mode=b.dataset.autoMode;redraw()});$$('[data-auto-scenario]').forEach(b=>b.onclick=()=>{autoUI.scenario=b.dataset.autoScenario;redraw()});$$('[data-auto-shadow]').forEach(b=>b.onclick=()=>{autoUI.shadow=!autoUI.shadow;redraw()});$$('[data-auto-bound]').forEach(b=>b.onchange=()=>{const key=b.dataset.autoBound;autoUI[key]=b.value;if(AUTO_TIERS.indexOf(autoUI.min)>AUTO_TIERS.indexOf(autoUI.max)){autoUI[key==='min'?'max':'min']=b.value;}redraw()});$$('[data-try-auto]').forEach(b=>b.onclick=()=>{state.routing=autoUI.mode;state.model=autoUI.shadow?'gpt-5.4-mini':'auto:'+autoUI.mode;persist();goto('chat');setTimeout(()=>{const input=$('#chat-input');if(input){input.value=AUTO_SCENARIOS.find(s=>s.id===autoUI.scenario).prompt;input.focus();}},0)});$$('[data-auto-save]').forEach(b=>b.onclick=()=>{state.routing=autoUI.mode;state.model=autoUI.shadow?'gpt-5.4-mini':'auto';persist();saveAuto();toast('Applied to the next demo request')});$$('[data-auto-reset]').forEach(b=>b.onclick=()=>{Object.assign(autoUI,{scenario:'rewrite',mode:'balanced',min:'simple',max:'reasoning',shadow:false});redraw()});}
function decisionForPrompt(prompt){const text=prompt.toLowerCase();const scenario=/prov|proof|deriv|convergence/.test(text)?'proof':/debug|concurr|distribut|engineer/.test(text)?'code':/tool|delivery/.test(text)?'tools':'rewrite';const auto=state.model==='auto'||state.model.startsWith('auto:');const mode=auto&&state.model.includes(':')?state.model.split(':')[1]:state.routing;return simulateAuto({...autoUI,scenario,mode,providers:state.providers,shadow:!auto,pinned:state.model});}

const DOCS=[{id:'quickstart',group:'START',title:'Your first auto-routed request',lead:'A small change to the model field. A visible decision on the response.'},{id:'auto-routing',group:'ROUTE',title:'Auto model routing',lead:'Match request complexity to a model tier, then inspect the choice.'},{id:'policies',group:'OPERATE',title:'Policies & safe rollout',lead:'Understand which settings are preferences and which are constraints.'},{id:'errors',group:'REFERENCE',title:'Routing errors',lead:'Distinguish an unavailable router from a request with no eligible model.'}];
let docsQuery='',roadFilter='all';
function publicNav(active){return `<header class="site-nav"><a class="brand" href="#/">${brand(true)}</a><nav class="public-links" aria-label="Product navigation">${[['docs','Docs'],['pricing','LLM pricing'],['roadmap','Roadmap']].map(([id,n])=>`<a href="#/${id}" class="${active===id?'accent':''}">${n}</a>`).join('')}<a class="btn small" href="#/chat">Playground ${icon('arrow')}</a></nav></header>`;}
function docsBody(id){if(id==='quickstart')return `<h2 id="doc-overview">Enable, send, inspect.</h2><p>Configure a provider and enable <code>routing.auto.enabled</code> in the gateway. Then send a Responses API request using an auto alias.</p><pre class="raw-box">${esc('curl "$AURA/v1/responses" \\\n  -H "Authorization: Bearer $AURA_API_KEY" \\\n  -H "Content-Type: application/json" \\\n  -d \'{"model":"auto:balanced","input":"Explain this payload."}\'')}</pre><h2 id="doc-details">Read the decision</h2><p>The response’s <code>model</code> identifies the concrete model. Inspect <code>metadata.aura.routing</code> for its tier, candidates, constraints and reason.</p><a class="btn primary" href="#/docs/auto-routing">Understand auto routing ${icon('arrow')}</a>`;
if(id==='policies')return `<h2 id="doc-overview">Preview before applying.</h2><p>Keep a concrete model pinned and enable <code>shadow_for_pinned_models</code>. The pinned model still answers; the shadow decision records what auto would select.</p><div class="notice">Estimated shadow savings are counterfactual estimates, not realized savings or proof of equivalent answer quality.</div><h2 id="doc-details">Three scopes, clearly separated.</h2><table><thead><tr><th>Scope</th><th>Where it belongs</th></tr></thead><tbody><tr><td>Gateway defaults</td><td>Admin Settings → GET / PUT /admin/settings</td></tr><tr><td>Organization policy</td><td>Organization detail → settings.routing.auto</td></tr><tr><td>Request preferences</td><td>POST /v1/responses → routing</td></tr></tbody></table><p>Request preferences cannot loosen organization tier bounds or allow/deny policy. Tool continuation stays on the previous model when eligible and sufficiently strong.</p><h2>Budget semantics</h2><p><code>max_cost_usd</code> uses the learned cost model. It is not a guaranteed billing cap: without predictions it degrades to no budget, and when nothing fits the router can ignore the budget and explain this in its reason.</p><h2>Classifier privacy</h2><p>Heuristic and learned classifiers use in-process numeric features. The optional LLM classifier sends a numeric summary and an excerpt of user text to its configured model.</p>`;
if(id==='errors')return `<h2 id="doc-overview">Start with the error code.</h2><div class="error-guide"><h3>404 · model_not_found</h3><p>Auto routing is disabled for the gateway or organization, or the auto alias is unknown. Check configuration and the enabled aliases returned by <code>GET /v1/models</code>.</p><h3>503 · no_eligible_model</h3><p>No configured model satisfies the request constraints. Check provider availability, capability requirements, tier bounds and allow/deny policy.</p></div><h2 id="doc-details">Escalation has a boundary.</h2><p>Eligible provider failures can retry the next candidate, first in-tier and then above it, subject to configured attempts. Streaming escalation occurs only before the first event; do not promise transparent retry after output starts.</p><a class="btn" href="#/console/routing">Explore the dry-run concept ${icon('arrow')}</a>`;
return `<h2 id="doc-overview">One alias. Four tiers.</h2><p>Send <code>model: "auto"</code>. Aura scores complexity, maps the request to simple, medium, complex or reasoning, and selects an eligible model. The default within-tier policy picks the cheapest eligible candidate.</p><div class="doc-mode-grid">${[['auto:cost','Bias toward cheaper tiers'],['auto:balanced','Neutral score offset'],['auto:quality','Bias toward stronger tiers']].map(([a,b])=>`<div><code>${a}</code><p>${b}</p></div>`).join('')}</div><h2 id="doc-details">Inspect the choice.</h2><p>Use the response model for what actually answered. Use routing metadata for why. A shadow decision must be visibly labeled because its selected model did not answer.</p><pre class="raw-box">${esc(JSON.stringify({model:'auto:balanced',input:'Explain this payload.',routing:{min_tier:'simple',max_tier:'reasoning',sticky:true,classifier:'heuristic'}},null,2))}</pre><div class="notice">Tools require a capable model and at least the medium tier. Images, context capacity, provider availability and allow/deny patterns also constrain selection.</div><h2>Evaluate before rollout.</h2><p>Start with shadow decisions and representative tasks. Inspect outcomes and estimated savings separately. Then use a limited rollout with rollback criteria; a lower tier does not guarantee equivalent quality.</p><div class="hero-actions"><a class="btn primary" href="#/console/routing">Explore a decision ${icon('arrow')}</a><a class="btn" href="#/docs/policies">Read policy semantics</a></div>`;}
function renderDocs(id){const d=DOCS.find(x=>x.id===id)||DOCS[1];$('#app').innerHTML=`<div class="container">${publicNav('docs')}<div class="docs-layout"><aside class="docs-sidebar"><div class="eyebrow">DOCUMENTATION</div><label class="search-field">${icon('search')}<input id="docs-search" aria-label="Search documentation" placeholder="Find a guide…" value="${esc(docsQuery)}"></label><nav aria-label="Documentation">${DOCS.filter(x=>(x.title+' '+x.group).toLowerCase().includes(docsQuery.toLowerCase())).map(x=>`<a class="${x.id===d.id?'active':''}" href="#/docs/${x.id}"><small>${x.group}</small>${x.title}</a>`).join('')||'<p class="tiny muted">No matching guide. Try “routing”.</p>'}</nav><p class="tiny dim">Curated prototype articles.<br>Production documentation remains in the repository.</p></aside><main class="docs-article" id="main"><div class="eyebrow">GUIDE / ${d.group}</div><h1 class="serif">${d.title}</h1><p class="doc-lead">${d.lead}</p><div class="doc-meta"><span>Reviewed against source</span><span class="mono">ca6d517</span><span>Design proposal</span></div>${docsBody(d.id)}<footer class="doc-footer"><a href="https://github.com/UmaiTech/aura-llm-gateway/blob/ca6d517/docs/api/auto-routing.md" target="_blank" rel="noopener">View source guide ${icon('external')}</a><button class="text-button" data-copy="${esc(location.href)}">Copy page link ${icon('copy')}</button></footer></main><aside class="docs-toc"><div class="eyebrow">ON THIS PAGE</div><button data-doc-anchor="doc-overview">Overview</button><button data-doc-anchor="doc-details">Implementation details</button><a href="#/chat">Try in playground ↗</a></aside></div></div>`;$('#docs-search').oninput=e=>{docsQuery=e.target.value;const pos=e.target.selectionStart;renderDocs(id);bindCommon();$('#docs-search').focus();$('#docs-search').setSelectionRange(pos,pos)};$$('[data-doc-anchor]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.docAnchor).scrollIntoView({behavior:'smooth'}));}
const ROADMAP=[
 {status:'released',tag:'v0.20.0 · 22 OCT 2026',title:'Operate the gateway live',text:'Runtime gateway settings, refreshed model catalog and synthetic router training traces.',link:'https://github.com/UmaiTech/aura-llm-gateway/blob/ca6d517/CHANGELOG.md'},
 {status:'released',tag:'v0.18.0 · 09 SEP 2026',title:'Explainable auto model routing',text:'Complexity tiers, shadow decisions, organization overrides, learned classifiers, outcome signals, predicted costs and provider-failure escalation.',link:'https://github.com/UmaiTech/aura-llm-gateway/blob/ca6d517/CHANGELOG.md'},
 {status:'merged',tag:'MERGED TO MAIN · RELEASE NOT ASSERTED',title:'Provider prompt caching',text:'Cache-hit reporting and billing landed in #243 after the v0.20.0 release commit. Keep merged work separate from published releases.',link:'https://github.com/UmaiTech/aura-llm-gateway/pull/243'},
 {status:'proposed',tag:'PROPOSED / PRIORITY 01',title:'Make routing decisions easy to trust',text:'Unify the decision inspector across chat and admin. Add a clear dry-run surface and separate applied costs from estimated shadow savings.'},
 {status:'proposed',tag:'PROPOSED / PRIORITY 02',title:'Keep public information current',text:'Generate release history from canonical metadata. Give docs a task-based start, and make pricing freshness and missing values explicit.'},
 {status:'proposed',tag:'PROPOSED / PRIORITY 03',title:'Define the v1 reliability bar',text:'Publish measurable compatibility, rollout and recovery criteria before promising an availability SLA. Validate true budget enforcement as a separate feature.'}
];
function renderRoadmap(){const rows=ROADMAP.filter(r=>roadFilter==='all'||r.status===roadFilter);$('#app').innerHTML=`<div class="container">${publicNav('roadmap')}<main id="main" class="public-main"><div class="eyebrow">BUILDING IN THE OPEN</div><h1 class="serif">What shipped.<br><span class="accent">What could come next.</span></h1><p class="public-lead">A release record you can verify, followed by proposed priorities. No invented dates or delivery commitments.</p><div class="road-summary"><strong>Latest tagged in reviewed changelog <span class="accent">v0.20.0</span></strong><span>Source snapshot ca6d517</span></div><div class="auto-modes road-filters" role="group" aria-label="Roadmap status">${[['all','All'],['released','Released'],['merged','Merged'],['proposed','Proposed']].map(([v,n])=>`<button data-road-filter="${v}" aria-pressed="${roadFilter===v}" class="${roadFilter===v?'active':''}">${n}</button>`).join('')}</div><div class="road-list">${rows.map(r=>`<article class="road-item"><div><span class="road-dot ${r.status}"></span><span class="eyebrow">${r.tag}</span></div><div><h2>${r.title}</h2><p>${r.text}</p>${r.link?`<a class="text-button" href="${r.link}" target="_blank" rel="noopener">View evidence ${icon('external')}</a>`:'<span class="tiny accent">Design recommendation · not an announced commitment</span>'}</div></article>`).join('')}</div><div class="notice">The reviewed roadmap still identifies v0.13 as latest shipped and v0.14 as active. Reconcile it with the changelog before publishing the production redesign.</div></main></div>`;$$('[data-road-filter]').forEach(b=>b.onclick=()=>{roadFilter=b.dataset.roadFilter;renderRoadmap();bindCommon()});}

const PRICE_FIXTURES=[
 {id:'gemini-3.1-flash-lite',provider:'Google',input:.10,output:.40,cache:.025,context:1000000,tools:true,vision:true},
 {id:'gpt-5.4-mini',provider:'OpenAI',input:.75,output:4.50,cache:.075,context:400000,tools:true,vision:true},
 {id:'claude-haiku-4-5',provider:'Anthropic',input:1,output:5,cache:.10,context:200000,tools:true,vision:false},
 {id:'claude-sonnet-5',provider:'Anthropic',input:3,output:15,cache:null,context:200000,tools:true,vision:true},
 {id:'local-model',provider:'Ollama',input:null,output:null,cache:null,context:null,tools:false,vision:false}
];
const priceUI={query:'',provider:'all',cap:'all',sort:'estimate',input:1000,output:300,requests:10000,cache:0,compare:[]};
function estimatePrice(m){if(m.input===null||m.output===null)return null;if(priceUI.cache>0&&m.cache===null)return null;return ((priceUI.input*(1-priceUI.cache/100)*m.input+priceUI.input*priceUI.cache/100*(m.cache||0)+priceUI.output*m.output)/1e6)*priceUI.requests;}
function pricingRows(){const q=priceUI.query.toLowerCase();const models=PRICE_FIXTURES.filter(m=>(m.id+' '+m.provider).toLowerCase().includes(q)&&(priceUI.provider==='all'||m.provider===priceUI.provider)&&(priceUI.cap==='all'||m[priceUI.cap]));return models.sort((a,b)=>{const av=priceUI.sort==='estimate'?estimatePrice(a):a[priceUI.sort],bv=priceUI.sort==='estimate'?estimatePrice(b):b[priceUI.sort];return (av??Infinity)-(bv??Infinity)});}
function priceCell(v){return v===null?'—':'$'+v.toFixed(v>0&&v<.1?4:2);}
function pricingTable(){const rows=pricingRows();return `<div class="table-wrap"><table><thead><tr><th>Compare</th><th>Model / provider</th><th>Input / 1M</th><th>Output / 1M</th><th>Cached input / 1M</th><th>Context</th><th>Workload estimate</th></tr></thead><tbody>${rows.map(m=>`<tr><td><input type="checkbox" data-compare="${m.id}" aria-label="Compare ${m.id}" ${priceUI.compare.includes(m.id)?'checked':''}></td><td><button class="text-button" data-price-detail="${m.id}">${m.id}</button><div class="tiny dim">${m.provider}</div></td><td class="mono">${priceCell(m.input)}</td><td class="mono">${priceCell(m.output)}</td><td class="mono">${priceCell(m.cache)}</td><td class="mono">${m.context?m.context.toLocaleString():'Unknown'}</td><td class="mono accent">${priceCell(estimatePrice(m))}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty"><h3>No matching models</h3><p>Clear filters or search for another model.</p></div>':''}</div><div class="table-footer"><span>${rows.length} fixture models · USD · illustrative prices</span><button class="text-button" id="price-clear">Clear filters</button></div>`;}
function compareHTML(){if(!priceUI.compare.length)return '<p class="tiny muted">Select up to three models to compare them side by side.</p>';return `<div class="price-compare">${priceUI.compare.map(id=>{const m=PRICE_FIXTURES.find(x=>x.id===id);return `<div><span class="eyebrow">${m.provider}</span><h3>${m.id}</h3><div class="compare-value">${priceCell(estimatePrice(m))}</div><p class="tiny muted">for your sample workload</p><div class="kv"><span>Tools</span><span>${m.tools?'Supported':'Not in fixture'}</span></div><div class="kv"><span>Vision</span><span>${m.vision?'Supported':'Not in fixture'}</span></div><button class="text-button" data-price-detail="${id}">Inspect assumptions ${icon('arrow')}</button></div>`}).join('')}</div>`;}
function renderPricing(){$('#app').innerHTML=`<div class="container">${publicNav('pricing')}<main id="main" class="public-main"><div class="eyebrow">LLM PRICE EXPLORER</div><h1 class="serif">Model prices.<br><span class="accent">Your workload.</span></h1><p class="public-lead">Compare model rates and estimate a workload in the same view. Then let the auto router narrow the eligible models for each request.</p><div class="notice">${icon('alert')}Design fixtures only — these are not live provider quotes. Production uses your existing /api/pricing feed and its scrape timestamps.</div><section class="panel price-calculator"><div><h2>Your sample workload</h2><p class="tiny muted">USD estimate, excluding cache writes, tool fees, taxes and provider-specific tiers.</p></div><div class="price-inputs">${[['input','Input tokens / request',1000000],['output','Output tokens / request',1000000],['requests','Requests',10000000],['cache','Cached input %',100]].map(([key,label,max])=>`<label>${label}<input type="number" min="0" max="${max}" step="1" data-price-number="${key}" aria-label="${label}" value="${priceUI[key]}"></label>`).join('')}</div></section><div class="filter-bar"><label class="search-field">${icon('search')}<input id="price-search" aria-label="Search models" placeholder="Search models or providers…" value="${esc(priceUI.query)}"></label><select class="select" id="price-provider" aria-label="Pricing provider">${['all','OpenAI','Anthropic','Google','Ollama'].map(v=>`<option value="${v}" ${v===priceUI.provider?'selected':''}>${v==='all'?'All providers':v}</option>`).join('')}</select><select class="select" id="price-cap" aria-label="Model capability">${[['all','Any capability'],['tools','Tools'],['vision','Vision']].map(([v,n])=>`<option value="${v}" ${v===priceUI.cap?'selected':''}>${n}</option>`).join('')}</select><select class="select" id="price-sort" aria-label="Sort prices">${[['estimate','Workload cost ↑'],['input','Input price ↑'],['output','Output price ↑']].map(([v,n])=>`<option value="${v}" ${v===priceUI.sort?'selected':''}>${n}</option>`).join('')}</select></div><section class="panel" id="price-table">${pricingTable()}</section><p class="tiny dim" style="margin:14px 0 30px">“—” means unavailable, never free. If cached pricing is unknown and cache share is nonzero, no estimate is shown.</p><section class="panel form-panel"><h2 style="margin-bottom:20px">Side-by-side comparison</h2><div id="price-comparison">${compareHTML()}</div></section><section class="bottom-cta"><div><h2>Price is one part of routing.</h2><p>Capability, complexity, context and provider availability also shape the choice.</p></div><a class="btn primary" href="#/console/routing">Explore auto routing ${icon('arrow')}</a></section></main></div>`;bindPricing();}
function refreshPrices(){$('#price-table').innerHTML=pricingTable();$('#price-comparison').innerHTML=compareHTML();bindPriceRows();}
function bindPriceRows(){$$('[data-compare]').forEach(b=>b.onchange=()=>{const id=b.dataset.compare;if(b.checked){if(priceUI.compare.length>=3){b.checked=false;toast('Compare up to three models');return;}priceUI.compare.push(id);}else priceUI.compare=priceUI.compare.filter(x=>x!==id);refreshPrices()});$$('[data-price-detail]').forEach(b=>b.onclick=()=>{const m=PRICE_FIXTURES.find(x=>x.id===b.dataset.priceDetail);showOverlay('Price assumptions',m.id,`<div class="drawer-body"><div class="notice">Illustrative fixture. Provider rates and capabilities require verification against the live catalog.</div><dl class="detail-stack"><div><dt>Input / 1M</dt><dd>${priceCell(m.input)}</dd></div><div><dt>Output / 1M</dt><dd>${priceCell(m.output)}</dd></div><div><dt>Cached input / 1M</dt><dd>${priceCell(m.cache)}</dd></div><div><dt>Workload estimate</dt><dd>${priceCell(estimatePrice(m))}</dd></div></dl><h3 style="margin:25px 0 15px">Calculation</h3><pre class="raw-box">requests × (
  uncached_input × input_rate
  + cached_input × cached_rate
  + output × output_rate
) / 1,000,000</pre><p class="tiny muted">Assumes the entered average token counts. Does not model output-length changes, cache writes, tool fees, long-context tiers or negotiated discounts.</p></div>`)});$('#price-clear').onclick=()=>{Object.assign(priceUI,{query:'',provider:'all',cap:'all',sort:'estimate'});renderPricing();bindCommon()};}
function bindPricing(){$('#price-search').oninput=e=>{priceUI.query=e.target.value;refreshPrices()};for(const key of ['provider','cap','sort'])$('#price-'+key).onchange=e=>{priceUI[key]=e.target.value;refreshPrices()};$$('[data-price-number]').forEach(el=>el.oninput=()=>{priceUI[el.dataset.priceNumber]=Math.min(Number(el.max),Math.max(0,Math.floor(Number(el.value)||0)));refreshPrices();el.setAttribute('aria-invalid',Number(el.value)<0||Number(el.value)>Number(el.max)?'true':'false');el.onchange=()=>{el.value=priceUI[el.dataset.priceNumber];el.setAttribute('aria-invalid','false')};});bindPriceRows();}
let suiteView='console',adminPreview='traffic',playPreview='response';
function miniChart(){return `<div class="showcase-chart" role="img" aria-label="Illustrative hourly request activity">${[20,29,24,37,30,41,54,46,61,57,72,65,81,68,76,93,86,70,64,55,44,36,30,23].map((v,i)=>`<span style="height:${v}%;opacity:${i===15?1:.55}"></span>`).join('')}</div>`;}
function suiteHero(){return `<div class="suite-hero"><div class="suite-tabs" role="group" aria-label="Product preview"><button data-suite-view="console" aria-pressed="${suiteView==='console'}" class="${suiteView==='console'?'active':''}">${icon('grid')} Admin app</button><button data-suite-view="chat" aria-pressed="${suiteView==='chat'}" class="${suiteView==='chat'?'active':''}">${icon('chat')} Playground</button></div><div class="suite-hero-body">${suiteView==='console'?`<div class="showcase-caption"><span>Acme / Production</span><span class="status">Sample workspace</span></div><h3>Your gateway, at a glance.</h3><div class="suite-metrics"><div><span>Requests</span><strong>24,810</strong></div><div><span>Spend</span><strong>$18.42</strong></div><div><span>Success rate</span><strong>99.7%</strong></div></div>${miniChart()}<div class="suite-preview-row"><span class="status">OpenAI healthy</span><span class="status warning">Google degraded</span></div><a href="#/console" class="text-button suite-open">Explore traffic, cost and health ${icon('arrow')}</a>`:`<div class="showcase-caption"><span>Playground / auto:balanced</span><span class="status">Sample response</span></div><div class="showcase-prompt">Explain what happened to this request.</div><div class="showcase-answer"><img src="assets/aura-mark-violet.svg" alt=""><p>Aura selected a model, returned the response and kept the routing details alongside it.</p></div><div class="suite-metrics"><div><span>Model</span><strong class="small">gpt-5.4-mini</strong></div><div><span>Cost</span><strong>$0.0032</strong></div><div><span>Duration</span><strong>842 ms</strong></div></div><button class="text-button suite-open" data-showcase-chat>Open this sample in the playground ${icon('arrow')}</button>`}</div><div class="suite-preview-footer">Interactive product previews · illustrative data</div></div>`;}
function adminPreviewBody(){if(adminPreview==='health')return `<div class="showcase-caption"><h3>Provider health</h3><span class="eyebrow">SAMPLE SNAPSHOT</span></div>${['OpenAI','Anthropic','Google'].map((p,i)=>`<a class="showcase-provider" href="#/console/providers"><span class="provider-badge">${p[0]}</span><div><strong>${p}</strong><small>${['842 ms','1.21 s','2.51 s'][i]} average duration</small></div>${statusBadge(i===2?'Degraded':'Healthy')}${icon('chevron')}</a>`).join('')}<div class="showcase-insight">${icon('activity')}Spot the provider that needs attention, then inspect its requests.</div>`;if(adminPreview==='request')return `<div class="showcase-caption"><h3>One request. The useful details.</h3>${statusBadge('Completed')}</div><div class="showcase-request"><span class="mono accent">req_8f12</span><span class="muted">OpenAI / gpt-5.4-mini</span></div><div class="suite-metrics"><div><span>Duration</span><strong>842 ms</strong></div><div><span>Input tokens</span><strong>1,240</strong></div><div><span>Cost</span><strong>$0.0032</strong></div></div><div class="showcase-lifecycle"><span>Received</span>${icon('arrow')}<span>Routed</span>${icon('arrow')}<span>Completed</span></div><button class="btn small" data-open-request="req_8f12">Inspect this sample ${icon('panel')}</button>`;return `<div class="showcase-caption"><h3>Gateway overview</h3><span class="eyebrow">LAST 24H / SAMPLE</span></div><div class="suite-metrics"><div><span>Requests</span><strong>24,810</strong></div><div><span>Spend</span><strong>$18.42</strong></div><div><span>Avg duration</span><strong>842 ms</strong></div></div>${miniChart()}<div class="showcase-table-head"><span>Recent request</span><span>Duration</span><span>Cost</span></div>${seedRequests.slice(0,3).map(r=>`<button class="showcase-table-row" data-open-request="${r.id}"><span><strong>${r.id}</strong><small>${r.model}</small></span><span>${duration(r.latency)}</span><span>${cost(r.cost)}</span></button>`).join('')}`;}
function playPreviewBody(){if(playPreview==='routing')return `<div class="showcase-caption"><span class="eyebrow">REQUESTED: AUTO:BALANCED</span><span class="status">Applied · sample</span></div><h3>gpt-5.4-mini</h3><div class="tier-track">${AUTO_TIERS.map(t=>`<span class="${t==='medium'?'active':''}">${t}</span>`).join('')}</div><div class="kv"><span>Classified tier</span><strong>Medium</strong></div><div class="kv"><span>Signal</span><strong>Tool-assisted task</strong></div><div class="kv"><span>Constraint</span><strong>Tools-capable model</strong></div><div class="showcase-insight">${icon('route')}Cheapest eligible fixture in the medium tier. Open the sample to inspect candidates and raw metadata.</div>`;if(playPreview==='raw')return `<div class="code-header"><span class="eyebrow">METADATA.AURA.ROUTING / SAMPLE</span></div><pre class="raw-box">${esc(JSON.stringify({requested_model:'auto:balanced',mode:'balanced',classified_tier:'medium',tier:'medium',selected:'gpt-5.4-mini',shadow:false,reason:'Cheapest eligible fixture in medium.'},null,2))}</pre>`;return `<div class="showcase-caption"><span>Playground / auto:balanced</span><span class="eyebrow">SAMPLE CONVERSATION</span></div><div class="showcase-prompt">Use the tools to check delivery status and summarize it.</div><div class="showcase-answer"><img src="assets/aura-mark-violet.svg" alt=""><div><strong>Aura <span class="dim">/ gpt-5.4-mini</span></strong><p>This sample was routed to a tool-capable model in the medium tier. Inspect the decision to see why it was selected.</p></div></div><div class="showcase-chat-meta"><span>842 ms</span><span>$0.0032</span><span>1,550 tokens</span></div><div class="showcase-composer"><span>Explore the sample in the playground…</span><button class="icon-button" data-showcase-chat aria-label="Open sample conversation">${icon('send')}</button></div>`;}
function productShowcases(){return `<nav class="product-jump" aria-label="Explore Aura products"><a href="#admin-app" data-scroll="admin-app"><span>FOR OPERATORS</span>${icon('grid')} Admin app ${icon('arrow')}</a><a href="#playground-product" data-scroll="playground-product"><span>FOR BUILDERS</span>${icon('chat')} Playground ${icon('arrow')}</a><a href="#auto-router" data-scroll="auto-router"><span>FOR EVERY REQUEST</span>${icon('route')} Auto router ${icon('arrow')}</a></nav><section class="section product-showcase" id="admin-app"><div class="product-story"><span class="eyebrow">01 / THE ADMIN APP</span><h2>Run your gateway<br>with a clear view.</h2><p>See where traffic goes, what it costs and which providers need attention. Follow the overview down to the request that explains it.</p><ul class="product-benefits"><li>${icon('chart')}Read traffic, spend and success together.</li><li>${icon('activity')}Spot degraded providers and inspect requests.</li><li>${icon('users')}Keep operations and organization policy in reach.</li></ul><a href="#/console" class="btn primary">Explore the admin app ${icon('arrow')}</a><a href="#/console/requests" class="text-button product-secondary">Go straight to request logs ${icon('arrow')}</a></div><div class="product-window"><div class="product-window-top"><span>${icon('grid')} AURA ADMIN</span><span class="tiny dim">Interactive preview</span></div><div class="product-preview-tabs" role="group" aria-label="Admin app preview">${[['traffic','Traffic & cost'],['health','Provider health'],['request','Request detail']].map(([id,n])=>`<button data-admin-preview="${id}" aria-pressed="${adminPreview===id}" class="${adminPreview===id?'active':''}">${n}</button>`).join('')}</div><div class="product-window-body" id="admin-showcase-body">${adminPreviewBody()}</div><div class="suite-preview-footer">Illustrative workspace · click a request to inspect</div></div></section><section class="section product-showcase playground-showcase" id="playground-product"><div class="product-story"><span class="eyebrow">02 / THE PLAYGROUND</span><h2>Build with the response.<br>Learn from the details.</h2><p>Try a model, explore auto routing and inspect usage without leaving the conversation. Keep the answer and its explanation side by side.</p><ul class="product-benefits"><li>${icon('chat')}Explore a response with its actual model.</li><li>${icon('route')}Inspect tiers, constraints and candidates.</li><li>${icon('code')}Check tokens, cost and raw metadata.</li></ul><button class="btn primary" data-showcase-chat>Try a sample request ${icon('arrow')}</button><a href="#/chat" class="text-button product-secondary">Open a playground session ${icon('arrow')}</a><p class="product-demo-note">This design demo uses sample responses. No API key required.</p></div><div class="product-window"><div class="product-window-top"><span>${icon('chat')} AURA PLAYGROUND</span><span class="tiny dim">Interactive preview</span></div><div class="product-preview-tabs" role="group" aria-label="Playground preview">${[['response','Response'],['routing','Routing decision'],['raw','Raw JSON']].map(([id,n])=>`<button data-play-preview="${id}" aria-pressed="${playPreview===id}" class="${playPreview===id?'active':''}">${n}</button>`).join('')}</div><div class="product-window-body" id="play-showcase-body">${playPreviewBody()}</div><div class="suite-preview-footer"><span>Explore here. Inspect further in the app.</span><button class="text-button" data-showcase-chat>Open sample ${icon('arrow')}</button></div></div></section>`;}
function openShowcaseChat(){if(state.streaming)stopStream();const d=simulateAuto({scenario:'tools',mode:'balanced'});const r={...seedRequests[0],id:'req_product_demo',autoDecision:d};state.requests=state.requests.filter(x=>x.id!==r.id);state.requests.unshift(r);state.messages=[{role:'user',text:'Use the tools to check delivery status and summarize it.'},{role:'assistant',text:'This is a product-tour sample. Aura selected gpt-5.4-mini from the medium tier for a tool-assisted request.\n\nThe inspector shows the model, token usage, cost and routing decision. No tools or providers were contacted in this demonstration. You can find the same request in Console → Requests.',model:r.model,request:r}];state.activeRequest=r;state.chatStarted=true;state.inspectorTab='routing';state.sessionName='Explore an auto-routed response';goto('chat');render();}
function bindShowcase(){$$('[data-suite-view]').forEach(b=>b.onclick=()=>{suiteView=b.dataset.suiteView;const container=$('.suite-hero');container.outerHTML=suiteHero();bindShowcase();$('[data-suite-view="'+suiteView+'"]').focus()});$$('[data-admin-preview]').forEach(b=>b.onclick=()=>{adminPreview=b.dataset.adminPreview;$$('[data-admin-preview]').forEach(x=>{x.classList.toggle('active',x.dataset.adminPreview===adminPreview);x.setAttribute('aria-pressed',x.dataset.adminPreview===adminPreview)});$('#admin-showcase-body').innerHTML=adminPreviewBody();bindCommon()});$$('[data-play-preview]').forEach(b=>b.onclick=()=>{playPreview=b.dataset.playPreview;$$('[data-play-preview]').forEach(x=>{x.classList.toggle('active',x.dataset.playPreview===playPreview);x.setAttribute('aria-pressed',x.dataset.playPreview===playPreview)});$('#play-showcase-body').innerHTML=playPreviewBody();bindCommon()});$$('[data-showcase-chat]').forEach(b=>b.onclick=openShowcaseChat);}
applyTheme();render();
